#!/usr/bin/env bash
# Kernel and boot tuning for the data plane. WRITES GRUB CONFIG AND REQUIRES A REBOOT.
# In the product this is generated by vrx-agent (work item D0.6) from the hardware
# inventory - this script is the reference implementation and the lab shortcut.
set -euo pipefail
[[ $EUID -eq 0 ]] || { echo "run as root" >&2; exit 1; }

HUGEPAGES_1G="${HUGEPAGES_1G:-16}"     # 1 GB pages reserved for VPP
ISOLATED="${ISOLATED:-2-9}"            # cores handed to VPP workers
APPLY="${APPLY:-no}"                   # set APPLY=yes to actually write GRUB

CMDLINE="default_hugepagesz=1G hugepagesz=1G hugepages=${HUGEPAGES_1G} \
intel_iommu=on iommu=pt \
isolcpus=${ISOLATED} nohz_full=${ISOLATED} rcu_nocbs=${ISOLATED} \
intel_pstate=disable processor.max_cstate=1 intel_idle.max_cstate=0 pcie_aspm=off"

echo "Proposed kernel cmdline:"; echo "  $CMDLINE"; echo

cat > /etc/sysctl.d/80-vrx-dataplane.conf <<'SYSCTL'
vm.max_map_count = 3096000
vm.overcommit_memory = 0
kernel.shmmax = 68719476736
net.core.rmem_max = 67108864
net.core.wmem_max = 67108864
fs.file-max = 2097152
SYSCTL
sysctl --system >/dev/null

cat > /etc/security/limits.d/80-vrx.conf <<'LIMITS'
*    soft  memlock  unlimited
*    hard  memlock  unlimited
root soft  memlock  unlimited
root hard  memlock  unlimited
LIMITS

printf 'vfio-pci\nvfio_iommu_type1\n' > /etc/modules-load.d/vrx-dataplane.conf
modprobe vfio-pci || modprobe uio_pci_generic || true

systemctl disable --now irqbalance 2>/dev/null || true

if [[ "$APPLY" == "yes" ]]; then
  cp /etc/default/grub "/etc/default/grub.bak.$(date +%s)"
  sed -i "s|^GRUB_CMDLINE_LINUX_DEFAULT=.*|GRUB_CMDLINE_LINUX_DEFAULT=\"${CMDLINE}\"|" /etc/default/grub
  update-grub
  echo "GRUB updated - REBOOT REQUIRED."
else
  echo "sysctl, limits and modules applied. GRUB NOT touched."
  echo "Re-run with APPLY=yes to write the kernel cmdline (a backup of /etc/default/grub is kept)."
fi
